package game.agent;
import game.agent.web.*;import game.agent.llm.*;import java.util.*;import java.net.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class EvaluationHttpTest {
 @Test void dashboardCommandsAndAttachmentEnforceCookieCsrfAndOwnership()throws Exception{ProviderSelection unavailable=new ProviderSelection("openai","unavailable",1000,null,null);try(AgentWebServer server=new AgentWebServer(0,unavailable,null,true,null)){server.start();AgentWebServerTest.Browser alice=new AgentWebServerTest.Browser(server.getPort()),bob=new AgentWebServerTest.Browser(server.getPort());HttpURLConnection page=alice.connection("/evaluation/","GET");assertEquals(200,page.getResponseCode());page.disconnect();Map<String,Object> snapshot=AgentWebServerTest.read(alice.connection("/api/evaluation/batches","GET"));Map<String,Object> params=Json.object("models",Arrays.asList("baseline"),"scenarios",Arrays.asList("information"),"seeds",Arrays.asList(11),"repetitions",1,"starter","TREECKO","decisions",100,"wallMillis",10000,"prices",Collections.emptyMap());Map<String,Object> command=Json.object("requestId",UUID.randomUUID().toString(),"expectedRevision",snapshot.get("revision"),"command","CREATE","params",params);assertEquals(403,alice.post("/api/evaluation/commands",Json.write(command),alice.base,"wrong").getResponseCode());Map<String,Object> created=alice.post("/api/evaluation/commands",command);String batch=(String)Json.asObject(Json.asArray(created.get("batches")).get(0)).get("id");String download="/api/evaluation/batches/"+batch+"/download";assertEquals(404,bob.connection(download,"GET").getResponseCode());HttpURLConnection file=alice.connection(download,"GET");assertEquals(200,file.getResponseCode());assertEquals("attachment; filename=\"v4-batch-report.json\"",file.getHeaderField("Content-Disposition"));assertEquals(batch,AgentWebServerTest.read(file).get("id"));assertEquals(405,alice.connection("/api/evaluation/batches","DELETE").getResponseCode());}}
}
